const PPTX = require('pptxgenjs');

let pres = new PPTX();
// Set layout to wide for more space
pres.layout = 'LAYOUT_WIDE'; // 13.3" x 7.5"
pres.title = 'Top India';
pres.author = 'Generated by Titan';

// Define a theme color (optional)
pres.defineTheme({
  name: 'myTheme',
  colors: {
    background: 'FFFFFF',
    accent1: '003366', // dark blue
    accent2: '006699',
    accent3: '0099CC',
    accent4: '66CCFF',
    accent5: '99CCFF',
    accent6: 'CCE6FF',
    fill1: 'FFFFFF',
    fill2: 'F2F2F2',
    fill3: 'E6E6E6',
    line1: 'CCCCCC',
    line2: 'BFBFBF'
  }
});
pres.theme = 'myTheme';

// Slide 1: Title Slide
let slide1 = pres.addSlide();
slide1.addText('Top India', { x: 0.5, y: 1.5, fontSize: 44, color: '003366', bold: true });
slide1.addText('A Glimpse into India\'s Rich Heritage and Progress', { x: 0.5, y: 2.5, fontSize: 24, color: '006699' });
slide1.addText('Generated on ' + new Date().toLocaleDateString(), { x: 0.5, y: 3.5, fontSize: 18, color: '666666' });

// Slide 2: Overview
let slide2 = pres.addSlide();
slide2.addText('Overview', { x: 0.5, y: 0.5, fontSize: 32, color: '003366', bold: true });
slide2.addText([
  'Location: South Asia',
  'Area: 3.287 million km²',
  'Population: ~1.4 billion',
  'Capital: New Delhi',
  'Official Languages: Hindi, English (and 22 others)'
], { x: 0.5, y: 1.5, fontSize: 20, color: '000000', lineSpacing: 1.2 });

// Slide 3: Culture
let slide3 = pres.addSlide();
slide3.addText('Culture & Traditions', { x: 0.5, y: 0.5, fontSize: 32, color: '003366', bold: true });
slide3.addText([
  'Diverse festivals: Diwali, Holi, Eid, Christmas',
  'Classical dance forms: Bharatanatyam, Kathak, Odissi',
  'Rich culinary variety: North Indian, South Indian, Coastal',
  'Heritage sites: Taj Mahal, Jaipur Palaces, Hampi',
  'Bollywood: World\'s largest film industry'
], { x: 0.5, y: 1.5, fontSize: 20, color: '000000', lineSpacing: 1.2 });

// Slide 4: Economy
let slide4 = pres.addSlide();
slide4.addText('Economy & Growth', { x: 0.5, y: 0.5, fontSize: 32, color: '003366', bold: true });
slide4.addText([
  '5th largest nominal GDP globally',
  'Fastest-growing major economy',
  'Key sectors: IT services, manufacturing, agriculture',
  'Startup ecosystem: 3rd largest in world',
  'Major exports: software, textiles, pharmaceuticals'
], { x: 0.5, y: 1.5, fontSize: 20, color: '000000', lineSpacing: 1.2 });

// Slide 5: Technology & Innovation
let slide5 = pres.addSlide();
slide5.addText('Technology & Innovation', { x: 0.5, y: 0.5, fontSize: 32, color: '003366', bold: true });
slide5.addText([
  'Leading IT services exporter (TCS, Infosys, Wipro)',
  'Space program: ISRO\'s Chandrayaan, Mangalyaan',
  'Nuclear energy and renewable energy growth',
  'Digital India initiative: expanding internet access',
  'Thriving biotech and pharmaceutical sectors'
], { x: 0.5, y: 1.5, fontSize: 20, color: '000000', lineSpacing: 1.2 });

// Slide 6: Conclusion
let slide6 = pres.addSlide();
slide6.addText('Conclusion', { x: 0.5, y: 0.5, fontSize: 32, color: '003366', bold: true });
slide6.addText([
  'India blends ancient traditions with modern progress',
  'Opportunities in tourism, investment, and collaboration',
  'A vibrant democracy with a youthful population',
  'Inviting the world to experience its diversity'
], { x: 0.5, y: 1.5, fontSize: 20, color: '000000', lineSpacing: 1.2 });
slide6.addText('Thank You!', { x: 0.5, y: 3.5, fontSize: 28, color: '003366', bold: true, align: 'center' });

// Write the file
pres.write('output.pptx');

